INSERT INTO public.productos_menu (
  id_producto, nombre, descripcion, precio_venta, categoria, subcategoria, tipo,
  tiempo_preparacion_estimado, requiere_cocina, activo, imagen, url_imagen,
  pasos_preparacion, alergenos, consejo_emplatado
) VALUES
  ('prod_ent_charcuteria', 'Charcutería de elaboración propia', 'Selección de fiambres y embutidos artesanales curados en la casa.', 7500, 'Entradas', NULL, 'plato', 5, true, true, 'data:image/jpeg;base64,', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_ent_empanadas', 'Dúo de empanadas criollas cortadas a cuchillo', 'Dos empanadas tradicionales rellenas de carne vacuna cortada a cuchillo, cocidas al horno de barro.', 4800, 'Entradas Criollas', NULL, 'plato', 10, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', '["Pintar las empanadas rellenas con huevo batido.","Hornear en el horno a leña precalentado a 250°C durante 8 a 10 minutos.","Rotar las empanadas a mitad de cocción para lograr un dorado parejo y burbujeante."]'::jsonb, '["Gluten","Huevo"]'::jsonb, 'Servir en una canasta de mimbre o plato de madera criollo con una servilleta de tela rústica.'),
  ('prod_ent_peras_quesoazul', 'Pera asada con queso azul, nueces y miel', 'Peras asadas al horno con queso azul premium, nueces tostadas y miel orgánica sobre verdes.', 6800, 'Entradas', NULL, 'plato', 8, true, true, 'data:image/jpeg;base64,', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_ent_provolone', 'Provolone al hierro con orégano y oliva', 'Queso provolone fundido al hierro, perfumado con orégano silvestre y aceite de oliva extra virgen.', 5500, 'Entradas Criollas', NULL, 'plato', 10, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_fanta', 'Fanta Naranja (Lata)', 'Lata de Fanta Naranja de 354ml bien helada.', 2500, 'Bebidas sin Alcohol', 'Gaseosas', 'bebida', 15, false, true, 'data:image/jpeg;base64,', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_gaseosa', 'Gaseosa Línea Cola Fría', 'Lata 354ml bien helada en mesa (Coca-Cola, Zero, Sprite, Fanta).', 1200, 'Bebidas sin Alcohol', 'Gaseosas', 'bebida', 15, false, true, 'https://images.unsplash.com/photo-1622483767028-3f66f32aef97?w=400&q=80', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_pas_cintas_carbonara', 'Cintas finas al huevo a la carbonara', 'Pasta fresca al huevo salteada con yema de huevo, panceta crocante y parmesano rallado.', 12400, 'Pastas', NULL, 'plato', 12, true, true, 'https://images.unsplash.com/photo-1612874742237-6526221588e3?w=500&q=80', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_pas_cintas_estofado', 'Cintas finas al huevo con filetto y estofado', 'Pasta fresca al huevo con salsa filetto tradicional y estofado de ternera cocido a fuego lento.', 11800, 'Pastas', NULL, 'plato', 12, true, true, 'https://images.unsplash.com/photo-1551183053-bf91a1d81141?w=500&q=80', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_pas_cintas_hongos', 'Cintas finas al huevo con crema de hongos de pino', 'Pasta fresca al huevo con una deliciosa crema reducida de hongos de pino patagónicos.', 12800, 'Pastas', NULL, 'plato', 12, true, true, 'data:image/jpeg;base64,', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_pas_cintas_sepia', 'Cinta ancha de pasta al huevo con tinta de sepia', 'Pasta fresca al huevo saborizada con tinta de sepia natural, ideal para combinar con salsas cremosas.', 13200, 'Pastas', NULL, 'plato', 12, true, true, 'https://images.unsplash.com/photo-1551183053-bf91a1d81141?w=500&q=80', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_pas_crepes_espinaca', 'Crepes de espinaca y parmesano', 'Rellenos de espinaca a la crema gratinados con salsa blanca y parmesano.', 11500, 'Pastas Artesanales', NULL, 'plato', 12, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_pas_lasagna_pollo', 'Lasagna de pollo y espinaca al forno', 'Láminas de pasta rellenas de pollo desmechado, espinaca tierna y ricota, gratinadas con salsa blanca y pomodoro.', 12500, 'Pastas', NULL, 'plato', 15, true, true, 'https://images.unsplash.com/photo-1574894709920-11b28e7367e3?w=500&q=80', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_pas_ñoquis_boniato', 'Ñoquis de boniato con manteca y almendras', 'Ñoquis artesanales de boniato (batata dulce) salteados con manteca noisette y almendras tostadas.', 11200, 'Pastas Artesanales', NULL, 'plato', 12, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_pas_rotolo', 'Rotolo di tata relleno de espinaca y ricota', 'Rollo de pasta al huevo relleno de espinaca fresca, ricota artesanal y nuez moscada, gratinado al horno.', 12500, 'Pastas', NULL, 'plato', 15, true, true, 'data:image/jpeg;base64,', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_pes_pacu', 'Pacú con papas rústicas', 'Pacú fresco grillado a la plancha con papas rústicas al horno de barro con romero.', 17500, 'Pescados y Mariscos', NULL, 'plato', 18, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_pes_salmon', 'Salmón rosado', 'Sellado al hierro, servido sobre colchón de espárragos y emulsión de limón.', 23500, 'Pescados y Mariscos', NULL, 'plato', 16, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', '["Pintar la parte superior del filet de salmón con clara de huevo y rebozar con el mix de sésamo blanco y negro.","Sellar en plancha bien caliente por el lado de las semillas durante 2 minutos hasta dorar.","Dar vuelta y terminar la cocción por 4 minutos a fuego medio (debe quedar rosado y jugoso en el centro).","Blanquear los espárragos y saltearlos rápidamente con manteca."]'::jsonb, '["Pescado","Sésamo","Huevo","Lácteos"]'::jsonb, 'Disponer el colchón de espárragos en el centro, asentar el salmón encima y rodear con gotas de emulsión de limón.'),
  ('prod_pes_trucha', 'Trucha', 'Cocida a la plancha, terminada con almendras fileteadas tostadas.', 19500, 'Pescados y Mariscos', NULL, 'plato', 14, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_pos_flan', 'Flan casero tradicional con dulce de leche y crema', 'Flan de huevos de campo con caramelo clásico, acompañado de dulce de leche y crema batida.', 4500, 'Postres Tradicionales', NULL, 'postre', 5, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', '["Colocar en la base del molde el caramelo líquido hecho a base de azúcar quemada.","Mezclar huevos frescos, leche entera y azúcar sin batir en exceso para evitar burbujas de aire.","Colar la preparación y verterla suavemente sobre el molde con caramelo.","Cocinar a baño maría en el horno a 140°C durante 50 a 60 minutos. Enfriar por al menos 4 horas antes de desmoldar."]'::jsonb, '["Huevo","Lácteos"]'::jsonb, 'Servir una porción generosa acompañada con una quenelle de dulce de leche repostero y crema batida.'),
  ('prod_pos_lingote_choc', 'Lingote de chocolate', 'Suave mousse de chocolate belga y dulce de leche sobre base crujiente de galletas de cacao.', 5800, 'Postres', NULL, 'postre', 5, true, true, 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?w=500&q=80', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_pos_pannacotta', 'Panna cotta con frutos rojos', 'Clásico postre italiano de crema de leche y vainilla, cubierto de salsa tibia de frutos del bosque.', 4900, 'Postres Tradicionales', NULL, 'postre', 4, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL)
